"""Serialize this reviewer's passage judgments. Does not edit manuscript or ledgers."""
from pathlib import Path
import json
from datetime import datetime

ROOT=Path(__file__).parent
P=json.loads((ROOT/'place-input.json').read_text(encoding='utf-8'))
R={}
FIELDS=P['review_fields']

def unit(suffix, problem, prereq, definition, roles, setup, bridge, mechanism, trace, example, limits, alternatives, objection, claim_checks, question, answer, refs, findings=None):
    key=next(k for k in P['units'] if k.endswith('::'+suffix))
    u=P['units'][key]
    assert len(claim_checks)==len(u['claims']), (suffix,len(claim_checks),len(u['claims']))
    fields=dict(zip([FIELDS[i] for i in [0,1,2,5,6,7,8,9,10,11,12,15]],
        [problem,prereq,definition,roles,setup,bridge,mechanism,trace,example,limits,alternatives,objection]))
    fields[FIELDS[13]]='reader task: '+question+'; dependencies checked: '+prereq+'; reasoning chain: '+answer+'; unresolved: '+('see findings' if findings else 'none in Stage 1 text scope; artwork fidelity remains deferred')+'.'
    claims={}
    for row,check in zip(u['claims'],claim_checks):
        verdict='true as written'
        if check.startswith('C: '): verdict='condition stated';check=check[3:]
        elif check.startswith('N: '):verdict='not a claim';check=check[3:]
        claims[row[0]]={'verdict':verdict,'checked':check}
    R[key]={'status':'open' if findings else 'pass','findings':findings or [],
        'questions':[{'question':question,'answer':answer,'source_refs':[key+'::'+x if x.startswith('p') else x for x in refs]}],
        'fields':fields,'claims':claims}

unit('ch:PLACE-FIELDS',
 'p3-p7: explain multiple separated fields and different widths while preserving the physical distinction between a tunnel route, floor and room.',
 '00-reading-guide.md p27 teaches place cells and fields; 01-foundations.md teaches tuning and rate maps. p3 distinguishes coordinate dimension from tunnel width and height.',
 'p9 defines an upcrossing as an upward threshold passage and marks the first teaching term; p7 explains the hidden input before any formula.',
 'p7,p11: a cell receives an input function; position selects its value; the model predicts distributions across fixed maps. Recordings estimate rate, not that input.',
 'setting: p3 physical environments; roles: p7 spatial input and thresholded cell; objects and flow: input at a position to positive rate; assumptions: fixed map p11; verdict: adequate.',
 'p7: a proposed smooth random spatial input stands for average synaptic input; observed rate is a separate output. No temporal-noise interpretation is imported.',
 'p9: counts arise from crossings; counts combined with lengths and gaps can separate threshold from scale. This is borne out by PLACE-INFERENCE.',
 'p3 uses actual tunnel/floor/room coordinate examples; p5 compares a short-track hill with separated long-track fields.',
 'p5 establishes the observation to explain, and p9 states how counting answers the parameter question; no numerical result is promised in the opening.',
 'p11 explicitly excludes memory drift, spike timing and learning; p7 keeps the statistical prediction separate from a particular next field.',
 'Not applicable: p7-p9 introduce one paper and its statistical question; a circuit comparison belongs in PLACE-WIRING and the spherical alternative in PLACE-SLICES.',
 'objection: a spatial random function is being described as temporal neural noise; kind: correctness; target: p7,p11; disposition: does not apply; reason: the map is fixed and the spatial coordinate is expressly not time.',
 ['Mainali STAR Eqs.2-3 model latent input and thresholded rate; main Eq.1 predicts size distributions.',
  'C: Mainali Figs.2-3 test shape and topology beyond fitted means; additional rate gain is kept explicit later in PLACE-DATA and TOPOLOGY.',
  'C: Fixed sampled map is the specified model, Mainali Methods S1; no learned or time-varying map is asserted.'],
 'What is random, and what moves?',
 'The map varies across model draws or cells; an animal moves through one fixed draw. Physical position indexes input and expected rate, while crossings mark model-field boundaries.', ['p7','p9','p11'])

unit('sec:PLACE-GP',
 'p15: identical rate histograms can hide different spatial arrangements, so a joint rule for neighboring positions is needed.',
 'p17-p28 supplies finite joint Gaussian values and covariance; p34-p38 teaches stationarity, isotropy and smoothness before derivatives at p69.',
 'p21 defines GP; p28 defines joint Gaussian and independence; p34-p36 mark the three assumptions; p61-p67 defines the excursion set and connected field.',
 'p40-p50: h has input units, z is unit variance, q is dimensionless and a has Hz units; x is distance, not elapsed time.',
 'setting: one stationary spatial map; roles: h/z input, q threshold, a rate gain; objects and flow: normalize then rectify; assumptions: Gaussian finite distributions and required smoothness; verdict: adequate (p17-p50).',
 'p40-p50 absorbs the constant mean into threshold and normalizes input. Changing a preserves zero-rate boundaries, with a positive detection-cutoff exception stated.',
 'p69-p83: differentiating C(y-x) twice yields -C double-prime(0), so normalized slope variance is sigma^-2. Gaussian covariance gives the same sigma.',
 'p85 and fig:PLACE-GP-TO-FIRING set q=.8,a=6 Hz on one spatial map; its positive regions follow the explicit rectification.',
 'p85 introduces the chosen parameters; p93 interprets separated fields and repeats that both panels are spatial maps.',
 'p36-p38 differentiability and nondegeneracy; p50 the positive detection cutoff exception; p83 other covariances can share local scale.',
 'common problem: specify spatial dependence; options: Gaussian covariance versus other smooth covariances and exponential covariance; relationship: covariance choices in one model family; criteria: derivative regularity and long-distance structure; selection or scope: p38,p83 use Gaussian simulations, excluding nonsmooth exponential paths from derivative calculations; verdict: adequate.',
 'objection: marginal Gaussian values guarantee smooth paths; kind: correctness; target: p36-p38 and derivative formulas; disposition: does not apply; reason: the exponential-covariance counterexample expressly defeats this inference.',
 ['C: Differentiability is an extra covariance/sample-path requirement, stated in p36-p38 and required by Kac-Rice.',
  'A Gaussian finite vector is determined by its mean and covariance; Mainali Methods S1.',
  'For joint Gaussian subvectors the characteristic function factorizes when cross covariance vanishes; Methods S1 and author notes definitions.',
  'Rectification puts mass at zero and changes positive values; STAR Eq.3.',
  'C: In the constant-mean Gaussian setting, radial covariance implies rotational invariance of finite laws.',
  'C: Conditions are expressly the differentiable, nondegenerate model used by the crossing and Hessian arguments.',
  'Exponential covariance has a cusp at zero and is the stated counterexample.',
  'Constant mean can be subtracted while shifting threshold; C(0) is stationary input variance.',
  'Dividing h by sqrt(C(0)) gives variance one; positive excess is dimensionless, so gain a has Hz units.',
  'Mainali STAR Eq.3: gain absorbs sigma_h between [h-q sigma_h]+ and [z-q]+.',
  'Visible summary identifies Mainali Figure 1; source PDF page 4 verified by extracted caption.',
  'Mainali Figure 1A-F caption supports maps, random summation, lengths, gaps, log moments and four mice. Exact crop/pixel fidelity is deferred.',
  'Chain rule: partial_x C(y-x)=-C prime(y-x); partial_y then gives -C double-prime.',
  'Twice differentiating exp(-delta^2/(2 sigma^2)) at zero gives -sigma_h^2/sigma^2.',
  'C: Equal C(0) and C double-prime(0) fix only this local scale, not C at nonzero separations.',
  'Declared teaching simulation and q=.8,a=6 agree with SVG labels and rectification; independent reproduction of the random draw was not requested.',
  'Formula maps z<=.8 to zero and z>.8 to 6(z-.8); SVG text/caption agree. Artwork fidelity deferred.',
  'Local PDF page 13 is STAR Eqs.2-3.'],
 'Does the covariance imply the derivatives used for crossings?',
 'Only with the stated regularity. The section explicitly distinguishes joint Gaussian values, translation/rotation assumptions, and sample-path smoothness; it then obtains the distance scale from derivative covariance.', ['p21','p34','p35','p36','p38','p83'])

unit('sec:PLACE-KAC-RICE',
 'p97: count fields without solving every threshold root.',
 'PLACE-GP p36,p83 supplies smoothness and derivative variance; p99 supplies a simple crossing and positive slope before the narrow-band argument.',
 'p105 marks Kac-Rice and gives its counting meaning; p153 defines Q and Phi before endpoint use is interpreted.',
 'p99-p111: v is spatial slope; p(z,z prime) is joint density across maps; nu is expected upcrossings per distance.',
 'setting: finite track with connected active intervals; roles: upward crossing starts a field and the left endpoint may add one; objects and flow: count local bands, average, add endpoint; assumptions: simple crossings, stationary Gaussian law; verdict: adequate (p99,p145,p153).',
 'p105-p111 turns a finite vertical band into spatial width 2 epsilon/v and compensates the inverse-slope sampling with v.',
 'p123-p143: stationarity makes height-slope covariance zero; Gaussianity gives independence; a positive Gaussian first moment yields exp(-q^2/2)/(2 pi sigma).',
 'fig:PLACE-CROSSINGS has two upward crossings and one already-active left boundary; draw_place.py v06 implements this construction and the local band weighting.',
 'p113 introduces the boundary illustration; p121 explains its retained-clipping convention before p145 gives the exact finite-track identity.',
 'p143 exactness belongs to the regular smooth stationary Gaussian model, without a high threshold; p145,p153 distinguish clipped-field inclusion from exclusion.',
 'common problem: field count on a finite interval; options: all intersecting components versus complete fields only; relationship: different counting conventions; criteria: endpoint inclusion; selection or scope: retain all intersecting components and add Q(q); verdict: adequate (p121,p145,p153).',
 'objection: one upward crossing always corresponds to one counted field even at track boundaries; kind: correctness; target: p145-p153; disposition: does not apply; reason: the extra left-active component is counted explicitly.',
 ['Local linearization gives band width 2 epsilon/v; integrating v/(2 epsilon) gives one.',
  'C: A simple upward crossing has positive nonzero derivative by the specified regularity.',
  'Positive derivative excludes downward crossings in the narrow-band identity.',
  'Kac-Rice weights the density at height q by v, not the tail probability Q(q); Mainali S9-S13 and author notes.',
  'draw_place.py v06 defines the fixed curve and crossing count; SVG labels show 3=2+1 and both tangent weights. Pixel check deferred.',
  'C: p121 expressly defines the retained-boundary convention.',
  'Differentiate E[z(x)^2]=1: derivative is 2E[zz prime]=0 under smoothness.',
  'PLACE-GP derivative calculation gives variance sigma^-2; Gaussian derivatives remain jointly Gaussian.',
  'Positive normal first moment is 1/(sigma sqrt(2 pi)); multiply by phi(q).',
  'du=sigma^2 v dv gives the displayed substitution.',
  'Q is the standard normal upper-tail probability used for z(0)>q.',
  'Removing left/right clipped components changes N_L and hence its expectation.',
  'Mainali STAR Eq.8 equals L exp(-q^2/2)/(2 pi sigma)+Q(q).'],
 'Why is the endpoint term needed and why is slope weighting correct?',
 'The narrow-band width is inversely proportional to slope, so multiplying by slope makes one unit per crossing. A field already active at zero has no upward crossing inside the track, adding an indicator with expectation Q(q).', ['p105','p111','p145','p153'])

unit('sec:PLACE-INFERENCE',
 'p157: low counts can reflect either a high threshold or slow spatial variation.',
 'PLACE-KAC-RICE p143,p153 teaches nu and Q; p159 interprets occupied length before dividing by field intensity.',
 'p159-p170 defines per-field and per-gap means and distinguishes them from finite-sample ratio expectations.',
 'p159,p187: lengths/gaps are spatial metres; q and sigma are inferred model parameters; the 200m numbers are model calculations, not new recordings.',
 'setting: long stationary track or many maps; roles: occupancy Q and crossing intensity nu; objects and flow: two means to q and sigma; assumptions: suitable averaging and no clipping; verdict: adequate (p159-p187).',
 'p191-p200 connects recorded-cell selection to a zero-truncated count distribution rather than treating observed counts as unconditional.',
 'Adding means isolates scale; their ratio yields Q(q); invert Phi and recover sigma. Conditional Poisson mean follows by omitting n=0 then renormalizing.',
 'p187 recomputed Q=.1356660609, nu=.0362126851, means 3.74636845/23.86826429m and expected count 7.37820309.',
 'p187 explicitly labels fitted-model numbers; p200 shows 36.8% exclusion and conditional mean 1.5819767 for lambda=1, with the inference consequence.',
 'p170 ratio-of-expectations caveat; p189 mixing/decay caveat and periodic counterexample; p191 Poisson is an assumed selection example.',
 'common problem: separate threshold/scale and correct selection; options: count alone versus occupancy/length information, unconditional versus truncated Poisson; relationship: incomplete summaries versus identified parameters; criteria: distinguish parameters and sample inclusion; selection or scope: p157-p200 uses both summaries and stated conditioning; verdict: adequate.',
 'objection: stationarity implies independent rare fields or an exact Poisson count at q=1.1; kind: correctness; target: p189,p191; disposition: does not apply; reason: decay and high-threshold qualifications are explicit, and the exact mean is kept separate from the distributional approximation.',
 ['C: Mainali S14-S15 give occupancy/intensity stationary means with long-track boundary neglect stated.',
  'C: p170 retains suitable averaging and expressly excludes expectation-of-finite-ratio interpretation.',
  'Q+Phi=1; adding and dividing the preceding means gives both identities.',
  'Invert Phi(mu_g/(mu_s+mu_g)); substitute into the sum to recover sigma.',
  'Recomputed using NormalDist tail and exp: .1356661,.03621269,3.746368,23.868264; Mainali Fig.4A supplies 1.1/2.4.',
  'Algebraic inverse of the unrounded model means recovers q and sigma.',
  '200*.036212685123+.135666060946=7.3782030856.',
  'A periodic smooth Gaussian process has persistent spatial dependence; stationarity alone cannot give independent distant events.',
  'A high excursion has a paired up/down boundary on its short length scale; rare-field mixing refers to separated excursions.',
  'C: Renormalizing Poisson probabilities for n>=1 gives the expression and lambda/(1-exp(-lambda)).',
  'n=0 contributes zero to E[N], proving the conditional mean identity.',
  'exp(-1)=.367879 and 1/(1-exp(-1))=1.581977.',
  'The conditional mean exceeds lambda; treating it as lambda overstates unconditional expected fields.',
  'Mainali STAR Eq.5 and Parameter inference in 2D explicitly condition on at least one field.'],
 'Can the two means identify q and sigma without assuming a Poisson field process?',
 'Yes. Occupancy and the exact Gaussian crossing intensity yield the two means and their inversion. Poisson behavior is a separate high-threshold/mixing approximation, used conditionally for the cell-selection example.', ['p159','p170','p187','p189','p200'])

unit('ch:PLACE-SIZES',
 'p3 asks how a common spatial model gives different full size distributions across dimensions after mean size is known.',
 'PLACE-INFERENCE supplies the mean; p7 restates z,q,sigma,a,d and the firing rule.',
 'p5 explains the local downward parabola before the next section defines Hessian; p7 repeats only the needed symbols.',
 'p5-p7: excess height determines radius, geometry converts radius to spatial size; no dynamical process is introduced.',
 'Not applicable: p3-p7 introduce a mathematical change of scale and geometry, not an additional interacting system.',
 'p5 links one radius to length, area or volume and separates a geometry conversion from a new biological mechanism.',
 'p5 identifies high-peak shape then geometric conversion; the following sections derive these steps.',
 'p5 track/arena/room supplies the three geometric cases; numerical examples occur in PLACE-SIZE-LAW.',
 'p3 asks the distribution question; p5 states the conditional calculation used to answer it.',
 'p5 expressly separates approximate high-threshold sizes from the exact selected-boundary slope law.',
 'Not applicable: p3-p7 set up the paper-derived size calculation, with its alternative empirical distribution compared in PLACE-DATA.',
 'objection: the exact crossing mean makes all size predictions exact at finite threshold; kind: correctness; target: p5; disposition: does not apply; reason: the opening labels the high-threshold approximation and gives the slope law a separate exact argument.',
 ['A mean alone does not determine a distribution; many positive laws have the same mean.',
  'N: The question motivates a change of variables whose answer is derived in the following unit.',
  'Same normalized rectification as PLACE-GP; dimensions and gain are restated.'],
 'Which promised results are approximate?',
 'The near-peak parabola and size distributions use a high threshold; the selected crossing-slope law is exact under the earlier smooth stationary Gaussian assumptions.', ['p3','p5','p7'])

unit('sec:PLACE-RARE-PEAKS',
 'p11: explain the histogram shape left unresolved by an exact mean length.',
 'PLACE-GP supplies isotropic derivative covariance; p15-p18 state regularity, q to infinity and component sampling; p22,p29 teach Hessian and Gaussian conditioning before their use.',
 'p22 marks Hessian with curvature meaning; p29 defines delta_ij and proves conditional mean by an independent Gaussian remainder; p75 defines Rayleigh through square-root exponential.',
 'p37-p65: epsilon is peak excess, U=q epsilon, r_star is radius and s full length; actual maximum selection is distinguished from fixed-location conditioning in p35.',
 'setting: one typical high component away from boundaries; roles: height, curvature and gradient; objects and flow: conditional parabola to radius to excess-height law; assumptions: p15-p20 high-threshold reconstruction, not a general theorem proof; verdict: adequate.',
 'p65,p78 distinguishes full length from radius and volume cube root from volume; the exponent two concerns rate versus a linear size.',
 'Conditional Hessian mean is -b/sigma^2 I with bounded variance; local expansion gives r_star=sigma sqrt(2 epsilon/q). Peak tail ratios tend to exp(-u) at epsilon=u/q.',
 'p80 checks finite-threshold empirical/model exponents 1.42/1.46 and 1.75/1.71 against source Fig.3C-D; they are not called limiting exponents.',
 'p37 sets peak at origin and zero gradient; p73-p80 interprets length distribution and rate-width scaling, then explains finite-threshold departures.',
 'p20,p63 retain theorem/remainder limits; p35 notes maximum-selection weighting; p80 warns shape fluctuations matter at moderate q.',
 'common problem: describe a selected peak; options: fixed-location Gaussian conditioning versus a randomly selected maximum; relationship: distinct sampling distributions; criteria: correct curvature weighting and high-q leading order; selection or scope: p35 retains the weighting distinction while using its leading limit; verdict: adequate.',
 'objection: conditioning on a high value at a fixed point is identical to sampling maxima; kind: correctness; target: p35,p49-p63; disposition: does not apply; reason: maximum curvature weighting and component/remainder qualifications are explicit, so only the leading asymptotic shape is claimed.',
 ['C: p15-p20 states q tends to infinity, smoothness and typical-component sampling.',
  'C: Count-once component sampling is stated and later contrasted with slices.',
  'Source Methods S4 is a sketch; guide explicitly limits its reconstructed argument.',
  'Conditional covariance of a jointly Gaussian Hessian is independent of b; its mean scales as b.',
  'C: Positive epsilon and zero gradient define the selected local maximum used for Taylor expansion.',
  'C: At high threshold regular excursions are dominated by single maxima; main S12 and S24 support the limiting count ratio.',
  'Expanding -(q+epsilon)^2/2+q^2/2 gives -q epsilon-epsilon^2/2.',
  'At epsilon=u/q the exponent is -u-u^2/(2q^2); limit exp(-u).',
  'C: Leading high-q count from S16 includes q^(d-1); EC unit derives the same factor.',
  '((q+u/q)/q)^(d-1)=(1+u/q^2)^(d-1) tends to one.',
  'A 1D symmetric interval has full length twice radius.',
  'Cube root of volume has length units; proportional geometric constants do not change the exponent.',
  'Mainali Figure 3C labels and caption: data 1.42, model 1.46.',
  'Mainali Figure 3D labels: 1.75/1.71 and cube-root-volume x axis.',
  'C: finite q values need not equal the asymptotic exponent two; p80 keeps this distinction.',
  'Mainali Figure 5A-C shows field shapes, multiple peaks and power-law slopes versus threshold.',
  'Mainali Figure 4C compares 6m tunnel shape/rate-size behavior and peak inset.',
  'Visible summary correctly names original Figure 5, PDF page9.',
  'Mainali Fig.5 caption and A-D labels support threshold simplification and short-tunnel width comparison; pixel fidelity deferred.'],
 'Does the local high-peak argument justify the width constant and exponential excess?',
 'Under the stated limiting regime, the Gaussian conditional curvature gives a parabola with q/(2 sigma^2), yielding full width 2 sqrt(2) sigma sqrt(U)/q. The ratio of high-peak counts at q+u/q and q tends to exp(-u), with multiple-peak and remainder control acknowledged as outside the local sketch.', ['p22','p29','p35','p37','p49','p63','p65'])

unit('sec:PLACE-SIZE-LAW',
 'p93: radius and dimensional size have different distributions and units.',
 'PLACE-RARE-PEAKS p63,p65 gives U exponential and the radius; p95 defines unit-ball volume and gamma before transforming size.',
 'p95 defines Gamma and v_d; p164 defines Weibull with scale/shape; p146 explains dimensions of beta.',
 'p97-p127: d is physical spatial dimension; s is length/area/volume; beta rescales s^(2/d); the high-q formula and empirical fitted scale are different.',
 'setting: limiting round excursion; roles: U excess, r_star radius, s dimensional size; objects and flow: monotonic variable transformation; assumptions: high-q and one component per draw; verdict: adequate (p97-p125).',
 'p146-p156: w removes units while U=w^(2/d) also removes shape differences; the reader is not told unit removal alone collapses the densities.',
 'Jacobian d(beta s^(2/d))/ds produces the density; substitution gives normalization and Gamma moments; inversion of the mean gives beta.',
 'p166,p168 recomputed means .50132565m,.25132741m^2,.12599688m^3 and finite-q errors 45.98156%,3.730079%.',
 'p166 fixes sigma=1m,q=5 in the limiting calculation; p168 compares against the earlier exact 1D mean and interprets the error.',
 'p114,p125 keep spherical/high-threshold scope; p164 explains integrable 3D divergence; p178 does not infer simulation errors from printed algebra.',
 'common problem: predict mean/shape at finite threshold; options: limiting density, exact 1D crossing mean, finite-threshold simulation; relationship: approximation versus exact expectation versus numerical model; criteria: finite-q accuracy; selection or scope: p168 displays measured approximation errors and motivates the simulation comparison; verdict: adequate.',
 'objection: the supplement contradicts the full-width constant and beta inferred from the mean; kind: correctness; target: p174-p176 and core formulas; disposition: does not apply; reason: current guide correctly repairs the printed algebra, confirmed by direct viewing of supplement PDF pages13-15 and by the independent crossing-mean limit.',
 ['Unit-ball formula gives standard ball volume and follows from the Gaussian integral; elementary recomputation for d=1,2,3.',
  'Gamma(3/2)=sqrt(pi)/2, Gamma(2)=1, Gamma(5/2)=3sqrt(pi)/4 give 2,pi,4pi/3.',
  'Definition integral converges for t>0; correct scope stated.',
  'Integration by parts yields Gamma(n+1)=n! for nonnegative integers.',
  'C: Substitute radius sqrt(2)sigma sqrt(U)/q into v_d r^d, then solve for U.',
  'SVG formula labels and draw_place.py v07 match radius, full width, ball sizes and exponents; original pixels not accepted here.',
  'C: The text explicitly restricts roundness to the limiting approximation.',
  'C: U has the limiting exponential density from the preceding peak calculation.',
  'Jacobian is (2 beta/d)s^(2/d-1); Mainali Eq.1.',
  'C: beta(q,sigma) is labeled leading high-threshold, not an identity at finite q.',
  'Mean integral gives Gamma(1+d/2) beta^(-d/2); solve by dividing by mean before raising 2/d.',
  'Substitute u=beta s^(2/d), so p(s)ds=e^-u du.',
  'For k>0, exponential U has all positive moments, so all stated size moments exist.',
  's^k=beta^(-kd/2)U^(kd/2); integrating gives Gamma(1+kd/2).',
  's has units length^d and beta length^-2 from its explicit formula.',
  'beta s^(2/d) is dimensionless; derivative of the transform has units inverse-size.',
  'beta^(d/2)s cancels length^-d against length^d.',
  'u=w^(2/d) and its survival is e^-u by construction.',
  'Formula, SVG labels and transformed survival agree; 3D density diverges as w^-1/3 but is integrable. Extended pixels deferred.',
  'Local main PDF page3 contains Eq.1, printed1111.',
  'Table caption accurately names the three row dimensions.',
  'Set d=1 in Eq.1: 2 beta s exp(-beta s^2), zero at s=0.',
  'Set d=2: beta exp(-beta s), mean1/beta.',
  'Set d=3: (2beta/3)s^-1/3 exp(-beta s^(2/3)); integral finite and Weibull shape2/3.',
  'C: With positive beta, k=2/d,b=beta^(-d/2) gives the stated survival.',
  'P(0<s<delta)=1-exp(-beta delta^(2/3)) tends to zero.',
  'C: p166 declares a chosen limiting calculation, not a measurement.',
  'Recomputed (sqrt(2pi)/5)^d for d=1,2,3: .501325655,.251327412,.125996880.',
  'sqrt(2pi)*2.4/1.1=5.469; dividing by exact3.746368 gives45.98156% excess.',
  'At q=5 the same ratio minus1 is .0373007934.',
  'C: Direct source PDF confirms printed S18,S23,S25 errors; these alone say nothing about implementation or fitted data.'],
 'Are the size constants and normalization consistent with the exact 1D crossing result?',
 'Yes. The transformed density integrates to one, the Gamma moments fix beta by division by the mean, and the leading 1D mean sqrt(2pi)sigma/q is the large-q limit of Q(q)/nu(q). The finite-q numerical comparison explicitly shows the approximation error.', ['p125','p136','p146','p166','p168','p174','p175','p176'])

unit('sec:PLACE-SLICES',
 'p184: matching whole volumes does not establish how activity is arranged inside them.',
 'PLACE-GP p21 gives finite Gaussian vectors; PLACE-SIZE-LAW distinguishes dimension and size. p186 explains restriction before applying dimensional size laws.',
 'p188 defines the new counted object as a connected interval or patch in the slice, not the original component.',
 'p186-p190: the line/plane samples physical positions; original fields may be missed or split; the sampling rule determines the observed length population.',
 'setting: line or plane through a fixed higher-dimensional map; roles: original component and sliced component; objects and flow: restrict then threshold or reverse those operations; assumptions: isotropy for the shared scale and spatially selected slices; verdict: adequate (p186-p190).',
 'p186: subset of a jointly Gaussian vector remains Gaussian; thresholding commutes pointwise with restriction. p190 includes hit probability and off-centre cuts.',
 'The restricted covariance is C((t-t prime)v); with unit v and isotropy it has sigma unchanged. Size predictions then use the dimension of the slice.',
 'p194-p195 maps Figure2C/D/E to lengths/areas/counts and H/I/J to lengths/areas/volumes; S2 supplies a fitted-volume spherical counterexample.',
 'p184 poses a spatial-structure test; p206 concludes that matching volumes alone is insufficient after the slice and topology comparisons.',
 'p190 prohibits converting once-per-field radius samples directly into uniformly positioned line samples; high-threshold qualifications are inherited from the size law.',
 'common problem: match higher-dimensional maps; options: thresholded Gaussian field and volume/peak-matched spherical fields; relationship: competing statistical constructions; criteria: slice distributions and topology beyond fitted volumes; selection or scope: p206 and S2 distinguish them; verdict: adequate.',
 'objection: each original sphere supplies an equally likely diameter to a sampled line; kind: correctness; target: p190; disposition: does not apply; reason: both size-dependent hit probability and noncentral cuts are stated before interpreting the figure.',
 ['C: A straight line is parameterized by x0+t v; same scale requires the stated unit direction/isotropy.',
  'Finite restriction takes a subvector of Gaussian evaluations, retaining joint Gaussianity.',
  'For each line position, z(x)>q is the same test before or after restriction.',
  'Spatially sampled lines weight fields by hit probability and include off-centre chords; p190 states both.',
  'Mainali Fig.2A-J caption confirms the dimensional organization.',
  'Visible summary identifies Mainali Fig.2, local PDF page5 with continued caption page6.',
  'C: Mainali Fig.2 supports the slice comparisons; the dimensional law is interpreted with the preceding high-threshold limits. Pixel fidelity deferred.',
  'Supplement Fig.S2 caption: spherical support, exact empirical joint volume/peak match, discrepant slices and EC.',
  'A matched-volume counterexample failing slices/topology establishes insufficiency of volume matching alone.',
  'Visible summary identifies Supplement Fig.S2 on PDF page3.',
  'Supplement Fig.S2A-C supports the caption; D-E concern curvature. Pixel fidelity deferred.'],
 'Why do line samples follow the lower-dimensional model rather than a once-per-field radius law?',
 'The process restricted to a fixed line is itself Gaussian with the restricted covariance. Its connected positive intervals are the samples of interest. Picking a whole field first and cutting its centre would create a different sampling distribution.', ['p186','p188','p190','p206'])

unit('sec:PLACE-SLOPES',
 'p219: a derivative sampled at a boundary is not sampled like a derivative at an arbitrary location.',
 'PLACE-KAC-RICE p105-p143 supplies v-weighted crossings and height-slope independence; p221 reuses that integral.',
 'p221-p229 defines the upcrossing slope density and distinguishes it from a half Gaussian at uniform spatial samples.',
 'v is normalized input slope; av is rate slope. p243 states that measured boundary slopes are finite differences over .1m, not input measurements.',
 'setting: selected simple crossings; roles: slope v and height density; objects and flow: restrict crossing count by slope then normalize; assumptions: stationary differentiable Gaussian map; verdict: adequate (p221-p229).',
 'p243 bridges continuous derivative to two adjacent recorded rate samples and states spatial-resolution limits.',
 'The q-dependent height density cancels. Positive Gaussian slope density weighted by v and normalized yields sigma^2 v exp(-sigma^2 v^2/2).',
 'p233-p239 independently derives full width from vx-qx^2/(2sigma^2), then transforms the exact slope density to beta=q^2/(8sigma^2).',
 'The folded independent check states high-threshold approximation before solving the second root; it verifies the earlier width constant.',
 'Exact slope law does not make the local-parabola width conversion exact; p233 calls it high threshold. p243 distinguishes finite difference from hidden input.',
 'common problem: distribution of positive derivatives; options: uniform positive slopes versus slopes selected at crossings; relationship: different sampling measures; criteria: crossing intensity weighting; selection or scope: p221-p229 chooses the v-weighted law; verdict: adequate.',
 'objection: multiplying a Gaussian derivative by a positivity indicator produces the boundary law; kind: correctness; target: p221-p229; disposition: does not apply; reason: the additional v factor is retained and its origin was derived in Kac-Rice.',
 ['Kac-Rice numerator restricted to v..v+dv is proportional to v p_zprime(v)dv.',
  'Normalize v sigma exp(-sigma^2v^2/2)/sqrt(2pi) by1/(sigma sqrt(2pi)), yielding the density shown.',
  'Author notes Theorem2.3 gives the same selected-slope law; a half normal lacks the v factor.',
  'C: Solving x(v-qx/(2sigma^2))=0 gives second root2sigma^2v/q within the stated parabola.',
  'C: Jacobian dv/ds=q/(2sigma^2) yields2beta s exp(-beta s^2), beta=q^2/(8sigma^2).',
  'Mainali Figure3A labels width, max rate, peak count and boundary slopes.',
  'Mainali STAR Boundary slopes specifies two consecutive samples separated by .1m.',
  'Visible summary names Figure3, local PDF page7.',
  'Mainali Fig.3A-H includes all described shape, slope and EC comparisons; pixel fidelity deferred.'],
 'Is the Rayleigh slope law exact while the width check is approximate?',
 'Yes. Height-slope independence removes q from the crossing-slope distribution without requiring high q. Width uses a local high-threshold parabola, so its change-of-variable check retains that approximation.', ['p221','p229','p233','p239','p243'])

unit('ch:PLACE-TESTS',
 'p3: maps with equal size/count summaries can have different holes, raising a stronger test and a circuit-inference question.',
 'PLACE-FIELDS and PLACE-SIZES establish maps, dimensions and summaries; p7 explicitly restores q,sigma,a,d and separates d from diffusion D.',
 'p5 describes connected regions/holes in ordinary words before the Euler definition in the next unit.',
 'p5-p7: fixed spatial map, observed environment boundary, measured summaries and random input sum have separate roles.',
 'setting: test map geometry then consider circuit input; roles: recordings, statistical model, candidate weighted inputs; objects and flow: compare predicted summaries then assess mechanism; assumptions: same fixed map model; verdict: adequate (p5,p7).',
 'p5 distinguishes measured maps from a possible generating sum; no circuit identification is promised.',
 'The plan progresses from geometric constraints through fitted quantities to a sufficient random-summation mechanism.',
 'p3 compares ring/tunnel configurations while holding basic field summaries equal; numerical EC examples follow.',
 'p3 states the limitation, p5 states the three checks, p7 bounds the objects they act on.',
 'p5 expressly leaves circuit assumptions and measurements visible, rather than deriving wiring from geometry.',
 'Not applicable: p3-p7 motivate three complementary checks; the actual competing circuit explanations are supplied in PLACE-WIRING.',
 'objection: matching topology uniquely proves a random circuit; kind: correctness; target: p3,p5; disposition: does not apply; reason: the opening asks how much agreement establishes and promises to expose additional assumptions.',
 [], 'What additional evidence will geometry supply?',
 'It can distinguish maps whose field summaries agree, but the chapter separately tracks fitting and circuit assumptions before interpreting that evidence.', ['p3','p5','p7'])

unit('sec:PLACE-TOPOLOGY',
 'p11: count and total area leave holes unresolved as threshold changes.',
 'PLACE-GP gives Gaussian derivatives; PLACE-RARE-PEAKS gives Hessian conditioning; p13-p19 teaches EC and Betti counts; p31 states the Morse theorem used, without claiming its proof.',
 'p13 EC, p19 Betti numbers, p31 critical point and Morse theory are marked and explained. p33,p41 define lambda and phi before density calculations.',
 'p43-p51: eta_j are signed densities, not positive field counts; p85 specifies faces of a nonperiodic box; p107-p115 separately approximates high-q component counts.',
 'setting: smooth isotropic Gaussian map on interval/square/cube; roles: interior critical points and boundary faces; objects and flow: signed Hessian count plus face contributions to EC; assumptions: nondegenerate critical points and retained intersecting components; verdict: adequate (p31,p33,p85).',
 'p117 maps an extra rate cutoff t to normalized level q+t/a and retains the fitted gain; rate cutoffs cannot directly expose below-original-threshold input geometry.',
 'Determinant expectations lambda^j times b,b^2-1,b^3-3b integrate to phi(q),q phi(q),(q^2-1)phi(q). Face multiplicity cancels sign factors to binomial(d,j)L^j.',
 'p16-p17 disks/ring/ball/shell verify Betti counting; p105 recomputation .5+30/(2pi)-1000/(2pi)^2=-20.0556476.',
 'p105 interprets negative EC as holes, not negative fields; p115 checks the high-q mean against the independent size law.',
 'p31 states the theorem rather than proves it; p98 distinguishes ordinary and periodic boxes and rectangular/general domains; p107-p115 labels component-count approximation.',
 'common problem: predict geometry across thresholds; options: EC versus component count, volume-only versus full boundary formula; relationship: different statistic and approximation; criteria: holes and domain size; selection or scope: full exact box EC except in explicitly high-q volume-dominated limit; verdict: adequate.',
 'objection: a negative expected EC invalidates a predicted field count; kind: correctness; target: p51,p105,p107; disposition: does not apply; reason: signed EC and positive counts are separated, and their approximate equality is limited to high threshold.',
 ['Betti sums: three disks b0=3; annulus b0=b1=1, so chi0.',
  'Ball chi1; solid torus b0=b1=1 gives0; shell b0=b2=1 gives2.',
  'Mainali STAR Euler characteristics uses the alternating Betti sum; dimensions0,1,2 match components,loops,cavities.',
  'draw_place.py topology_field and v08 define nested thresholds and component/hole counts; SVG labels match -1,0,4,3. Pixel fidelity deferred.',
  'Taylor2006 Eq.5.1 gives Hermite-polynomial EC densities; Mainali STAR Eqs.8-10 give the box formulas.',
  'C: j<=3 and lambda=sigma^-2 are explicit restrictions/definitions.',
  'C: Kac-Rice zeros weighted by |det H| and superlevel Morse signs yield det(-H); regularity p31 required.',
  'phi is the standard normal density.',
  'Isotropic derivative covariance is lambda I; Gaussianity yields independent gradient components and density at0.',
  'Multiply determinant mean, gradient density and Gaussian integrals; agrees Taylor Eq.5.1 for j1,2,3.',
  'Conditional mean -H=b lambda in1D.',
  'Expand2x2 determinant: b^2lambda^2+E[G11G22-G12^2]=lambda^2(b^2-1).',
  '3x3 determinant has three pair terms -b lambda^3; odd centered Gaussian products vanish.',
  'Sum gives lambda^3(b^3-3b).',
  'Using phi prime=-b phi, each displayed antiderivative has the stated vanishing infinity boundary.',
  'd(-q phi(q))/dq=(q^2-1)phi(q); integrate q..infinity gives q phi(q).',
  'C: p85 explicitly selects nonperiodic closed geometry and retained intersecting components.',
  'C: Independent symmetric normal derivatives have sign probability1/2 per normal direction; isotropic smooth model stated.',
  'Face counts2^(d-j)binomial(d,j) times probability2^-(d-j) give the coefficients; matches STAR Eqs.8-10.',
  'Nonzero lower-dimensional face terms are lost if only volume is kept; they can dominate small domains.',
  'Recomputed at r10,q0: -20.0556476178.',
  'C: High-q regular isolated excursions have single-peak blob limit, qualified by the prior high-peak assumptions.',
  'C: Keep volume eta_d and highest q power; Mainali Supplement S16.',
  'C: Exact EC includes holes/boundaries while high-q component approximation removes those leading complications.',
  'Mainali Figure3F-H plots EC as cutoff varies, not a single field count.',
  'With rateF=a[z-q]+, additional nonnegative cutoff only accesses z>q+t/a.',
  'Betti-sum changes permit nonmonotonic EC; source Fig.3F-H and STAR EC.'],
 'Do the higher-dimensional formulas count fields exactly?',
 'They count expected Euler characteristic exactly for the stated smooth Gaussian box setting. Fields equal EC only when components have no holes, used here as a high-threshold approximation. The signed densities and explicit boundary terms prevent conflating these quantities.', ['p31','p51','p85','p98','p105','p107','p115'])

unit('sec:PLACE-DATA',
 'p121: judge additional predictions while tracking the statistics used in fitting and geometry-changing processing.',
 'Earlier units teach mean/count/size/EC; p133 supplies centered log moments and lognormal meaning before their comparison.',
 'p133 defines skew, excess kurtosis and lognormal; p147 defines two principal-curvature summaries without making them size-law prerequisites.',
 'p121,p123: experiments estimate firing maps; simulations fit model parameters; original recording samples are not automatically final reanalysis samples.',
 'setting: reanalysis of different species/environments; roles: summaries fit q,sigma and gain, processed maps supply tests; objects and flow: table then histogram/shape/selection checks; assumptions: measurement definitions differ; verdict: adequate (p121-p145).',
 'p139-p145 explains .5Hz rectification,10cm bins,median filtering,outlier exclusion and extra1Hz cutoff as changes to analyzed geometry.',
 'p133-p135 distinguishes fitted means from histogram/log-moment comparisons and penalized in-sample likelihoods; p187 explains shared random thresholds across otherwise independent maps.',
 'Table separates six conditions and actual fit inputs; p187 gives the shared-cell-threshold mechanism for forward/backward correlations.',
 'p187 fixes the baseline mean threshold, fits two remaining distribution parameters to correlations, then identifies distribution agreement as the extra comparison.',
 'p123 missing final sample counts; p135 no held-out claim; p167 unclear3D distance conversion and cross-experiment limits; p187 no universal two-parameter extension claim.',
 'common problem: explain observed summaries; options: GP simulation, limiting Rayleigh/Poisson laws, fitted lognormal and spherical alternative; relationship: finite model versus asymptotic laws versus competitors; criteria: fitting burden and additional distribution/shape comparisons; selection or scope: p133-p147 distinguishes each test; verdict: adequate.',
 'objection: all shape agreement is parameter-free and based on held-out recordings; kind: correctness; target: table,p135,p187; disposition: does not apply; reason: fitted summaries, rate gain in TOPOLOGY, in-sample comparisons and fitted threshold-correlation parameters are disclosed.',
 ['Tracking fitted quantities prevents counting a calibration as an independent test; demonstrated by table and gain passage.',
  'C: STAR methods and supplement inspected; final long-tunnel/3D reanalysis counts are not clearly specified there. No original-study counts are substituted.',
  'Table is a fit-versus-comparison organization, as its caption says.',
  'STAR Parameter inference in1D matches mean length/gap for200m; Fig.1,3 comparisons as listed.',
  'STAR matches mean size and active fraction for6m; Figure5D caption explicitly says40 recorded cells.',
  'STAR matches mean size/count for130m bats and48m rats; supplement Fig.S1 matches rat lengths.',
  'Figure1F/main results say four mice and40m; STAR directly fits beta from length histograms and has an isolated rat label.',
  'STAR2D inference conditions counts onN>=1; main Fig.2C and Fig.3H identify20 sample maps for slices/EC.',
  'STAR3D inference uses mean volume and active fraction; Fig.2,3 and S2 give listed comparisons and room dimensions.',
  'Direct comparison: STAR e2 says rats in40m; Figure1F caption says mice.',
  'Figure1C distinguishes dashed limiting Rayleigh from orange simulation histogram.',
  'Figure1D caption distinguishes simulated gaps and dashed analytical prediction.',
  'Centered third/fourth standardized moments give skew/excess kurtosis; correct normalization stated.',
  'If log(s) is normal, m3=0,m4=3m2^2; finite samples need not equal population moments.',
  'STAR Fields in1D says10^4 matched-size simulations; likelihood/BIC/AIC described, with no held-out procedure.',
  'STAR Data processing: bat1D/3D maps rectified around.5Hz.',
  'C: Nonlinear threshold/filter/removal operations can change components,peaks,tails; the sentence says can.',
  'Field definition in STAR uses processed nonzero components, so these choices define the reported objects.',
  'Supplement Fig.S1 caption states15cm cutoff applied to model and removal of large empirical fields.',
  'Supplement Fig.S5 caption and plots describe threshold-sensitive moments and stable slope above1Hz.',
  'Supplement Fig.S2A-C spherical comparison; D-E mean/Gaussian curvature.',
  'C: S2 describes surface array gradients; finite derivative estimates depend on representation/resolution.',
  'Visible summary identifies Fig.S1 on supplementary PDFpage2.',
  'Supplement Fig.S1 caption supports matched minimum cutoff and log-moment comparisons; pixel fidelity deferred.',
  'Visible summary identifies Fig.S5; plots begin PDFpage7 and caption continues page8.',
  'S5A-B/caption supports threshold effects and1Hz stabilization; local link selects start of figure; pixels deferred.',
  'Figure4A-B table/trends compare a limited set of environments, not an experiment controlling every variable.',
  'nu=exp(-q^2/2)/(2pi sigma), mean=Q/nu show both positive fitted q and sigma affect counts and lengths.',
  'S3 count exponents .86,.82 imply propensity exponents -.14,-.18.',
  'C: Fig.4A gives4.0 for3D while STAR gives10cm resolution without an explicit conversion explaining that number; guide preserves uncertainty, not a metre claim.',
  'Visible summary identifies original Figure4, PDFpage8.',
  'Figure4A-C supports fitted-scale/environment and shape trends; the text restricts cross-experiment interpretation.',
  'Visible summary identifies Supplement FigureS3, PDFpage5.',
  'S3B fitted count slopes are below1; caption explicitly says weak propensity decrease.',
  'S4A-D: positive-conditioned skew normal threshold shared across two sampled maps per cell.',
  'S4D fixes mean to baseline and fits two remaining distribution parameters, beyond shared q,sigma.',
  'Visible summary identifies Supplement FigureS4, PDFpage6.',
  'S4A-F gives shared threshold, count/size correlations and retained length/gap comparisons; pixels deferred.'],
 'Which agreements are additional tests and which quantities were fitted?',
 'The table records different fitting summaries by dataset. Full histograms, slices and shapes provide additional comparisons, with firing gain and threshold-heterogeneity fits separately disclosed. Likelihood comparisons use the available data rather than a claimed held-out forecast.', ['p121','p123','p131','p133','p135','p145','p167','p187'])

unit('sec:PLACE-WIRING',
 'p200: identify a possible circuit origin for the statistical input while retaining what remains unmeasured.',
 'PLACE-GP gives covariance and finite Gaussian distributions; p202-p204 defines fixed input profiles, independent weights, and the expectation over weights.',
 'p202 explains effective signed weights relative to background; p210 supplies central-limit size/independence conditions rather than just naming the theorem.',
 'p204-p222: the same sampled W_i multiplies u_i at both spatial positions; averages vary weights, not time; positive and background-subtracted profiles are distinguished.',
 'setting: many spatially tuned inputs to one receiving cell; roles: fixed profiles and weights, optional background balance; objects and flow: weighted sum then thresholded rate; assumptions: independent zero-mean finite-variance weights, no dominant input, uniform dense coverage for stationarity; verdict: adequate (p202-p234).',
 'p210 bridges a sum of independent vectors at finite position lists to a GP limit; a large anatomical count alone does not establish enough active contributors.',
 'Weight independence cancels i!=j terms: C=v_W sum u_i(x)u_i(y). Uniform translated profiles give autocorrelation integral; Gaussian profile yields sqrt(2)b covariance width.',
 'p240-p247 explicitly completes the Gaussian autocorrelation: R0^2 sqrt(pi)b exp(-Delta^2/(4b^2)).',
 'p238 distinguishes changing amplitude via v_W/rho from changing spatial dependence via input width, then the Gaussian example establishes a width convention.',
 'p249 states sufficient mechanism is not unique identification, lists structured/correlated/plastic/recurrent possibilities, and limits stationarity near boundaries/landmarks/rewards.',
 'common problem: produce approximately Gaussian spatial input; options: independent random summation, partially correlated/structured input, plasticity or recurrent processing; relationship: alternative or mixed mechanisms; criteria: predicted covariance and direct input/connection evidence; selection or scope: p249 identifies random summation only as sufficient; verdict: adequate.',
 'objection: many anatomical inputs or Gaussian map statistics prove random biological synapses; kind: correctness; target: p202,p210,p249; disposition: does not apply; reason: effective signed weights, active-contributor conditions and lack of direct connection measurement are explicit.',
 ['Mainali MethodsS2 Eq.S3 is the same weighted sum; guide makes expectation over weights explicit.',
  'C: Multivariate CLT under normalization/no dominant term yields consistent Gaussian finite-dimensional limits as stated.',
  'MethodsS2 final paragraph requires many active presynaptic inputs within fields, not only large anatomical counts.',
  'C: Gaussian u0 is a chosen profile with amplitude R0 and standard deviation b.',
  'Complete square s^2+(s+Delta)^2=2(s+Delta/2)^2+Delta^2/2, then integrate exp(-(s+Delta/2)^2/b^2).',
  'C: Mainali Discussion addresses familiar relatively uniform environments; nonuniform locations/tasks can violate stationary-law assumptions.',
  'Mainali Figs.1-5 support the linked statistics; p251 immediately separates statistical success from unique mechanism.'],
 'What supplies Gaussianity, stationarity and spatial width?',
 'The many-small-input limit supplies Gaussian finite distributions; uniform spatial coverage supplies stationarity; the autocorrelation of input tuning supplies covariance shape and width. Fixed weight variance changes amplitude, and these statistical facts do not identify a unique biological circuit.', ['p204','p210','p222','p224','p232','p234','p238','p247','p249'])

unit('ch:SYNTHESIS',
 'p3: avoid treating a spatial fit as maintenance evidence or a behavioral covariance as unique generator identification.',
 'PLACE-WIRING p249-p251 states sufficient versus unique mechanism; the earlier memory/eye chapters distinguish maintained state, downstream filter and observed motion.',
 'No new technical definition is required at p3-p5; spatial map, represented position and downstream movement are already taught and separated again in the next unit.',
 'p5 gives three distinct objects: spatial map, changing represented position and measured movement.',
 'setting: compare three papers; roles: map model, maintenance dynamics, downstream observation; objects and flow: compare evidence then introduce a conditional joint calculation; assumptions: no claim of a joint experiment; verdict: adequate (p3-p5).',
 'p3 keeps statistical description, proposed dynamics and measured behavior at separate explanatory levels.',
 'p5 motivates the shared-position calculation as a connection to test, not evidence already supplied.',
 'p5 previews a single common-position-error example developed in p60-p87.',
 'p3 asks the comparison problem, p5 outlines the calculation/evidence distinction used to answer it.',
 'p3 explicitly blocks unique neural-generator inference from a behavior model.',
 'common problem: relate the papers; options: conflate their position variables or distinguish map/dynamics/measurement; relationship: alternative interpretations, not competing algorithms; criteria: evidence scope; selection or scope: p3-p5 preserves the object distinctions; verdict: adequate.',
 'objection: the three papers jointly validate one circuit model; kind: correctness; target: p3-p5; disposition: does not apply; reason: the opening explicitly frames a comparison of separately supported claims and measurements still needed.',
 [], 'What conclusion is the synthesis entitled to draw?',
 'It can compare constraints and derive a conditional connection. It cannot turn agreement in separate models and organisms into a jointly tested circuit.', ['p3','p5'])

unit('sec:SYNTHESIS-QUESTIONS',
 'p9-p15: distinguish which position variable and question each paper addresses.',
 'Memory diffusion and readout chapters establish theta; eye chapters distinguish internal command/eye angle; place chapters establish physical x and static h_i(x). p15 recaps these exact distinctions.',
 'p11-p13 uses plain role labels spatial map, memory motion, observed movement rather than declaring a new common variable.',
 'p15 assigns theta(t) to attractor state, internal command versus angle to eye, x to physical animal location; the GP does not update remembered x.',
 'setting: proposed position representation; roles: map, maintained coordinate, downstream plant; objects and flow: coordinate selects rates and downstream mechanics transform command; assumptions: connections are proposed across separate models; verdict: adequate (p11-p25).',
 'Table maps random objects and observables across studies; it does not replace physical position with neural-state coordinates silently.',
 'p25 explains direct2012/2022 mechanism connection and why irregular place tuning still needs dynamics before joining it.',
 'tbl:SYNTHESIS-MODELS compares each random object with its governing assumptions and principal observable.',
 'p9 poses the question set; p25 states what remains missing to turn curves into a dynamic model.',
 'p25 explicitly excludes measuring Fisher information or equality in the2012 bound from the eye study.',
 'common problem: account for position representation and motion; options: three complementary studies; relationship: map statistics, maintenance constraint and filtered behavior evidence; criteria: random object and measured quantity; selection or scope: table and p25 keep different evidence levels; verdict: adequate.',
 'objection: shared upstream eye variability demonstrates equality in the memory information bound; kind: correctness; target: p25 and table; disposition: does not apply; reason: p25 expressly says neither Fisher information nor bound equality was measured.',
 ['Ben-Shushan main model and Figs.4-5 combine integrator diffusion with ocular filtering/feedback; it is labeled candidate.',
  'Table compares the three models under its stated four columns.',
  'Burak-Fiete2012 Eqs.1-5 and SI derive coordinate increments, diffusion and readout under neural/noise parameters.',
  'Ben-Shushan2022 Eqs.1-7 and Figs.2-5 distinguish shared/private/measurement contributions and movement MSD.',
  'Mainali2025 Eq.2 is a function of physical position, Eq.1 and Figs.1-5 concern field statistics.',
  'A map f_i(x) alone has no equation for x(t), as made explicit in the next unit.'],
 'Do the three uses of position name the same random object?',
 'No. The2012 coordinate labels maintained network states;2022 distinguishes an internal angle command from observed eye angle;2025 indexes static spatial input by animal location. Their possible coupling must be added and tested.', ['p11','p12','p13','p15','p25'])

unit('sec:SYNTHESIS-JOINT-CALCULATION',
 'p29: determine what rate changes follow when a fixed tuning map is evaluated at a moving estimate.',
 '01-foundations tuning/rate versus spikes; memory diffusion convention2Dt; ordinary Taylor expansion is in audience calculus baseline, with local linearization explained in02-memory-dynamics p97.',
 'p29 names f_i and x(t); p37 defines x0,delta x,t,D and its mean/variance before expanding.',
 'p35 distinguishes fixed f_i, time-varying x(t), expected rate R_i and actual spike-count variability.',
 'setting: one-dimensional maintained estimate over a short interval; roles: fixed tuning slopes and one shared displacement; objects and flow: x to f_i(x) to rate changes/covariance; assumptions: zero local mean,variance2Dt,small displacement; verdict: adequate (p29-p52).',
 'p35 makes the addition of time variation explicit while preserving static spatial tuning; no GP fit is said to determine diffusion.',
 'First-order expansion gives delta R_i=f_i prime delta x, whose covariance is product of slopes times2Dt, conditional on x0.',
 'p44 displays the centered-product calculation; the next unit substitutes slopes and diffusion to show negative covariance.',
 'p37 states interval/starting point and assumptions; p52 interprets which covariance was computed and which variability was omitted.',
 'p35 labels a guide construction; p52 excludes all network covariance, higher-order tuning and extra private/shared fluctuations, and warns near thresholds.',
 'common problem: explain correlated rate changes; options: common represented displacement,private noise,other shared noise; relationship: alternative/concurrent contributors; criteria: covariance alignment with slopes; selection or scope: p52 isolates only the common-position contribution; verdict: adequate.',
 'objection: the formula applies to every spiking-network covariance or across threshold kinks; kind: correctness; target: p52; disposition: does not apply; reason: both claims are expressly ruled out and the formula is conditional and local.',
 ['C: Zero-mean local displacement withvariance2Dt and sufficiently small change are stated assumptions, not measured facts.',
  'Taylor theorem gives first order plus quadratic remainder for locally smooth f_i.',
  'Cov(aX,bX)=ab Var(X); substitute slopes and2Dt, retaining leading-order qualification.',
  'p52 restricts the covariance to conditional expected-rate changes from one shared source.',
  'Rectification thresholds are nondifferentiable and large displacements make neglected curvature matter.'],
 'What does the shared covariance formula actually establish?',
 'It computes one conditional contribution: expected-rate changes caused by the same small represented displacement. It is a local Taylor consequence, not a complete stochastic neural-network model.', ['p29','p35','p37','p44','p52'])

unit('sec:SYNTHESIS-COVARIANCE-EXAMPLE',
 'p60-p73: explain opposite rate changes from the same position error without inferring direct inhibition.',
 'SYNTHESIS-JOINT-CALCULATION supplies Cov=2Dt f_i prime f_j prime; foundations defines covariance/correlation and local tuning.',
 'p60 defines units and all numbers; p75 states the optional10Hz baseline chosen for the drawing.',
 'p73: opposite signs arise from tuning slopes under one common displacement; no inhibitory synapse is identified.',
 'setting: two locally linear rate curves at one starting position; roles: slopes2,-1 Hz/m and common delta x; objects and flow: displacement to paired changes; assumptions: one source only for correlation-1; verdict: adequate (p60-p83).',
 'p75,p83 maps the shared scalar displacement to a line in a two-rate plane, while independent private variation adds spread around it.',
 '2Dt=.01m^2; variances=.04,.01Hz^2; covariance=-.02Hz^2; divide by standard deviations .2*.1 to get-1.',
 'A+.1m displacement produces+.2Hz,-.1Hz and covariance matrix [[.04,-.02],[-.02,.01]], rank1 and positive semidefinite.',
 'p60 provides the illustrative inputs; p73 interprets the sign; p87 says tuning-map alignment is needed for testing the shared-position account.',
 'p73 requires only the one source for correlation-1; independent nonzero private noise reduces magnitude. The curves are the local example, not global unbounded firing rates.',
 'common problem: explain negative covariance; options: opposite tuning under shared input versus an inhibitory connection; relationship: distinct mechanisms that may give the same sign; criteria: slope alignment and additional circuit evidence; selection or scope: p73 refuses synaptic inference from sign alone; verdict: adequate.',
 'objection: negative covariance proves inhibition; kind: correctness; target: p73; disposition: does not apply; reason: common displacement with opposite slopes reproduces it with no direct cell-cell connection.',
 ['N: Pure HTML container has no reader-visible scientific claim.',
  'C: Slopes2 and-1 Hz/m are chosen illustrative inputs.',
  'C: D=.01m^2/s and t=.5s are explicit suppositions.',
  '2*.01*.5=.01m^2.',
  '4*.01=.04Hz^2.',
  '1*.01=.01Hz^2 and2*(-1)*.01=-.02Hz^2.',
  'C: With only one shared source,-.02/sqrt(.04*.01)=-1. Independent added variance increases denominator.',
  'SVG labels and calculation give+.2,-.1 at+.1m, covariance-.02 and local baseline10. Artwork fidelity deferred.',
  'C: Alignment with fixed tuning slopes is a necessary comparison for this proposed mechanism, not a sufficient causal proof.'],
 'Does this example require an inhibitory connection?',
 'No. The shared displacement increases one cell and decreases the other because their fixed slopes have opposite signs. The arithmetic gives negative covariance and correlation-1 before adding other noise.', ['p60','p73','p75','p83','p87'])

unit('sec:SYNTHESIS-EVIDENCE',
 'p91: determine which observations could establish the proposed link, beyond the illustrative covariance calculation.',
 'Place data/gain passages; eye chi decomposition and timing chapter; memory information bound. p93-p97 explicitly recalls each source condition.',
 'No new technical terms are needed; fitted parameters, covariance, MSD and information rate were developed in their source chapters.',
 'p93 separates fitting and further predictions; p95 separates calibration and observation; p97 separates a mathematical bound from an experimental fit.',
 'setting: assess three kinds of support; roles: fitted spatial model,calibrated eye analysis,derived inequality; objects and flow: assumptions to predicted observables to appropriate tests; assumptions: compatibility must be checked; verdict: adequate (p93-p97).',
 'p95 keeps the movement-to-firing calibration and inverse neural prediction explicit; p97 requires information/time constants measured under compatible conditions.',
 'p93 additional shape tests constrain a fitted spatial description; p95 shared covariance plus time structure constrains sources; p97 scaling alone cannot identify an entire inequality.',
 'The three list entries are concrete evidence comparisons, not an artificial extra numerical example.',
 'p91 asks what remains to measure; p93-p97 identifies each source-specific limit and appropriate comparison.',
 'p93 rate gain/high-q versus simulations; p95 calibration,source correlations,two animals,horizontal movement; p97 compatible noise/model assumptions.',
 'common problem: judge support for a link; options: distribution fit, shared covariance/time test, mathematical inequality; relationship: complementary evidence types; criteria: fit burden and assumptions versus tested quantity; selection or scope: p93-p97 forbids treating one as the other; verdict: adequate.',
 'objection: increasing stationary motor-noise amplitude alone can reproduce arbitrarily growing integrator displacement; kind: correctness; target: p95; disposition: does not apply; reason: the statement holds for the compared stationary filtered motor source, whose lag shape changes in amplitude but does not become upstream integrated diffusion.',
 ['Mainali STAR matches log-log intercept for rate-width and mean max rate for EC; multiplier is disclosed.',
  'C: Under the stated independent-source decomposition, Cov(C+eta,C+epsilon)=Var(C); private noise alone cannot supply it.',
  'C: Ben-Shushan timing model and guide04b give stationary filtered-source versus accumulating-command lag shapes; changing only amplitude preserves the stationary shape.',
  'Ben-Shushan source reports two macaques,horizontal350ms analysis; calibration and source independence are analysis assumptions.',
  '1/N alone omits prefactors,tau and information J; different averaging mechanisms share this scaling.'],
 'Why are the three forms of evidence not interchangeable?',
 'Fitted spatial summaries constrain maps, shared neural-behavior covariance and MSD constrain source contributions, and the2012 inequality constrains a specified stochastic memory model. Testing the combined account needs compatible measurements of all relevant quantities.', ['p91','p93','p95','p97'])

unit('sec:SYNTHESIS-RELATED',
 'p101: identify assumptions tested or changed by related work, while keeping mechanisms open.',
 'Foundations supplies CA3/CA1/grid anatomy; prior chapters teach line attractors, diffusion and field statistics; p103 defines path integration and p109 defines dendrite before using those roles.',
 'p103 marks path integration as updating a position estimate from movement; p109 marks dendrite as branching neural input structure.',
 'p103 separates goldfish experiments from macaque variance estimates; p107 separates original recordings/reanalysis andCA3/CA1; p109 separates plasticity evidence from a fitted random map.',
 'setting: compare related theory and recordings; roles: source studies constrain dynamics,anatomy,plasticity or perception; objects and flow: each result changes a particular assumption; assumptions: species/model differences retained; verdict: adequate (p103-p111).',
 'p107 relates large-tunnelCA3/CA1 field counts without equating distinct regions; p111 relates retinal sampling benefits without deducing the motion generator.',
 'p103 grid integration accumulates modeled errors; p105 coding/plasticity changes memory predictions; p109 dendritic events can change synapses/form fields; these mechanisms are compatible with descriptive Gaussian statistics.',
 'p107 gives the concrete later comparison: mostly single CA3 fields and multipleCA1 fields with similar sizes. Cached primary2026 text directly supports it.',
 'Each short entry names the paper question and ends with the limit of its relevance; this is a source comparison, not a full recreation of each external experiment.',
 'p103 numerical grid accuracy is simulation-specific; p107 cross-dimensional reanalysis not three new experiments; p111 sensory benefit not unique neural source.',
 'common problem: what mechanisms remain possible; options: recurrent integration,coding transformations,synaptic plasticity,structured connections,sensory benefit; relationship: complementary constraints and candidate mechanisms rather than one interchangeable list; criteria: which assumption each changes and what it measured; selection or scope: p103-p111 retains those distinctions; verdict: adequate.',
 'objection: successful random-field statistics rule out structured connectivity or learned fields; kind: correctness; target: p109; disposition: does not apply; reason: Druckmann connectivity and Bittner plasticity are explicitly retained as compatible and distinguishable by further measurements.',
 ['Burak-Fiete2009 primary PLOS abstract/results confines accuracy ranges to model architectures,noise and parameter choices; Seung/Aksay cached primary texts support integration context.',
  'Koyluoglu2017 primary eLife abstract compares direct/coded storage and human data; Seeholzer2019 primary abstract derives plasticity-dependent diffusion/drift. They change assumptions.',
  'Maimon2026 primary cached Results/Figs1-2 directly compareCA3/CA1 in matched large tunnels and report similar field-size distributions.',
  'Druckmann2014 primary abstract reports nonuniform clusteredCA3-CA1 synapses; Bittner2017 primary Methods/Results ties dendritic plateau events to potentiation and fields. Extra measurements can constrain candidate mechanisms.',
  'Nghiem2025 primary Results has17 subjects and retinal encoding model with an intermediate movement optimum; benefit alone cannot identify a generator.'],
 'Are the related-study summaries supported without claiming more than their designs establish?',
 'Yes. Primary abstracts/results support the particular model,region,plasticity and perception statements. The paragraph expressly keeps model-specific accuracy, separate experimental origins and unmeasured circuit mechanisms visible.', ['p103','p105','p107','p109','p111'])

unit('sec:SYNTHESIS-NEXT',
 'p115: design a possible joint test requiring maps and fluctuations from one population.',
 'SYNTHESIS-JOINT-CALCULATION establishes the conditional slope-covariance relation; evidence section supplies compatible assumptions and filters.',
 'No new definition is introduced; diffusion,covariance,tuning and observation filters refer back to their explicit earlier roles.',
 'p117-p120: experiment estimates tuning,measures fluctuations,fits diffusion and includes downstream filters if behavior is compared.',
 'setting: proposed follow-up in one population; roles: tuning map,represented-coordinate fluctuation,observation filter; objects and flow: estimate maps then test covariance alignment and compatible diffusion; assumptions: local approximation and measurement corrections; verdict: adequate (p115-p122).',
 'p120 keeps physical/neural observation filtering between internal representation and measured behavior.',
 'p117-p122 imposes both static and temporal constraints, which independently fit models do not provide.',
 'The numbered sequence is an explicitly proposed test, not an empirical result or a guarantee of unique diagnosis.',
 'p115 establishes proposed scope; p122 states the intended stronger constraint and explicitly denies replication by this guide.',
 'p119 compatible local range; p120 conditional behavior step; p122 static map does not determineD and diffusion does not determine field distribution.',
 'common problem: test the combined account; options: fit spatial statistics only,fit temporal diffusion only,joint measurements; relationship: partial versus combined constraints; criteria: compatibility in one population; selection or scope: p122 proposes joint work and leaves several assumptions to examine if it fails; verdict: adequate.',
 'objection: a failed joint test uniquely identifies which biological assumption is wrong; kind: correctness; target: p122; disposition: does not apply under the strongest reading; reason: the passage names spatial input,recurrent maintenance,filtering or coupling as candidate assumptions, rather than providing a unique diagnostic rule. Wording can make this non-uniqueness plainer in Stage2.',
 ['C: Local linearization and measurement-correction conditions explicitly constrain fitting range.',
  'A distribution over fixed spatial maps contains no time dynamics parameterD without an added motion model.',
  'A diffusion process for a coordinate does not specify f_i(x) or its excursion distribution; p122 lists candidate assumptions and labels proposed work.'],
 'Is this a supported result or a proposed experiment?',
 'It is a proposed follow-up. The derivation gives a testable covariance relation under conditions; the final paragraph states that neither standalone fit supplies the other model and that the guide has not replicated a joint result.', ['p115','p117','p118','p119','p120','p122'])

